    col_seps = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]

    def spans(length, seps):
        result = []
        start = 0
        for sep in seps:
            if sep > start:
                result.append((start, sep))
            start = sep + 1
        # The unbounded trailing margin is not a cell.
        return result

    row_spans = spans(h, row_seps)
    col_spans = spans(w, col_seps)
    out = [row[:] for row in grid]
    markers = {}
    for ri, (r0, r1) in enumerate(row_spans):
        for ci, (c0, c1) in enumerate(col_spans):
            colors = {grid[r][c] for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] not in (0, 8)}
            for color in colors:
                markers.setdefault(color, []).append((ri, ci))

    row_fills, col_fills = {}, {}
    for color, cells in markers.items():
        from collections import Counter
        row_counts = Counter(r for r, _ in cells)
        col_counts = Counter(c for _, c in cells)
        for r, count in row_counts.items():
