                row_fills.setdefault(r, set()).add(color)
        for c, count in col_counts.items():
            if count >= 2:
                col_fills.setdefault(c, set()).add(color)

    # Paint whole cell-blocks; crossing lines combine by multiplication.
    for ri, (r0, r1) in enumerate(row_spans):
        for ci, (c0, c1) in enumerate(col_spans):
            colors = set(row_fills.get(ri, ())) | set(col_fills.get(ci, ()))
            if colors:
                value = 1
                for color in colors:
                    value *= color
                for r in range(r0, r1):
                    for c in range(c0, c1):
                        out[r][c] = value
    return out

